const spaces=[['Кофейни','Пахнет кофе.<br>Звучит прекрасно.','Мягкий соул, немного джаза и лёгкий грув. Музыка для неспешных разговоров и ещё одной чашки.','Soul / Jazz / Bossa Nova','#faf4e9'],['Рестораны','Вкус в каждой<br>ноте.','Деликатное сопровождение, которое оставляет место разговору и делает ужин особенным.','Lounge / Nu Jazz / Soul','#ffe5d7'],['Бары','Вечер набирает<br>обороты.','Глубокий бас, тёплый фанк и танцевальное настроение для встреч, которые хочется продлить.','Funk / Disco / Groove','#eee5fa'],['Магазины','Стиль, который<br>слышно.','Современный ритм для вашего пространства. Лёгкая электроника и уверенное настроение.','Indie Pop / Nu Disco','#e2f5ff'],['Отели','Добро пожаловать<br>в ваш ритм.','Спокойное звучание лобби и мягкий лаунж для отдыха. Атмосфера гостеприимства с первой ноты.','Lounge / Balearic / Jazz','#e1f4e9'],['Фитнес и SPA','Вдохновение<br>в движении.','Энергия для тренировок и спокойствие для восстановления. Разные форматы для разных зон.','Deep House / Ambient','#e4f7fc']];
const tabs=document.querySelector('#space-tabs');spaces.forEach((s,i)=>{const b=document.createElement('button');b.textContent=s[0];b.setAttribute('aria-pressed',i===0);b.onclick=()=>{tabs.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));const art=document.querySelector('#space-art');art.className='world world-'+i;art.style.backgroundPositionY=i<3?'0%':'100%';art.setAttribute('aria-label','3D-концепция: '+s[0]);document.querySelector('#space-title').innerHTML=s[1];document.querySelector('#space-desc').textContent=s[2];document.querySelector('#space-genre').textContent=s[3];document.querySelector('.space-stage').style.background=s[4]};tabs.append(b)});
const times=[['09:00','Morning Soul','Мягкое начало большого дня.','#fff1d9','none'],['13:00','Lunch Lounge','Лёгкость в самом разгаре дня.','#e6f6fc','brightness(1.12)'],['18:00','Sunset Groove','Тёплый грув на закате.','#ffd4ad','sepia(.3) saturate(1.2)'],['22:00','Night Disco','Вечер с собственным характером.','#d8d5ef','brightness(.6) hue-rotate(15deg)']];const tt=document.querySelector('#time-tabs');times.forEach((t,i)=>{const b=document.createElement('button');b.innerHTML='<span>'+t[0]+'</span><b>'+t[1]+'</b>';b.setAttribute('aria-pressed',i===0);b.onclick=()=>{tt.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelector('#day-hour').textContent=t[0];document.querySelector('#day-name').textContent=t[1];document.querySelector('#day-copy').textContent=t[2];document.querySelector('#day-scene').style.background=t[3];document.querySelector('#day-scene .world').style.filter=t[4];document.querySelectorAll('.style-name').forEach(x=>x.textContent=t[1])};tt.append(b)});
